head.b:skin:
/* =========================================================
   THE PWAVWE PAPERS — Editorial Blogger Theme
   Built for blogs.pwavwe.com
   Palette: paper / ink / oxblood / muted gold
   ========================================================= */

:root {
  --paper: #f7f4ee;
  --paper-2: #efe9df;
  --ink: #171717;
  --muted: #6f6a63;
  --line: #d7d0c6;
  --accent: #8b2432;
  --accent-2: #b28a4a;
  /* Fill colour behind white text (buttons, badges). Separate from --accent so
     dark mode can keep a bright link colour and still pass 4.5:1 on fills. */
  --accent-solid: #8b2432;
  --card: #fbf9f5;
  --shadow: 0 20px 60px rgba(23, 23, 23, .08);
  --serif: 'DM Serif Display', Georgia, serif;
  --sans: 'Inter', Arial, sans-serif;
  --max: 1240px;
  --reading: 760px;
}

html.dark {
  --paper: #131210;
  --paper-2: #1b1916;
  --ink: #f4efe8;
  --muted: #aaa39a;
  --line: #34302b;
  --accent: #d75d6f;
  --accent-2: #d0aa68;
  --accent-solid: #b3404f;
  --card: #191714;
  --shadow: 0 20px 60px rgba(0,0,0,.28);
}

* { box-sizing: border-box; }
html { overflow-x: clip; scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; height: auto; }
button, input { font: inherit; }
::selection { background: var(--accent-solid); color: #fff; }

.site-shell { min-height: 100vh; }
.wrap { width: min(calc(100% - 40px), var(--max)); margin: 0 auto; }

/* Keyboard users can jump past the header; hidden until focused. */
.skip-link {
  position: fixed; left: 12px; top: 12px; z-index: 3000;
  padding: 10px 16px; border-radius: 999px; background: var(--ink); color: var(--paper);
  font-size: .82rem; font-weight: 800; transform: translateY(-200%);
}
.skip-link:focus { transform: none; }
.visually-hidden {
  position: absolute !important; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; border: 0;
}

/* Reading progress */
.reading-progress {
  position: fixed; inset: 0 auto auto 0; z-index: 2000;
  width: 0; height: 3px; background: var(--accent);
  transition: width .08s linear;
}

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 1000;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--paper) 92%, transparent);
  backdrop-filter: blur(16px);
}
.header-inner {
  min-height: 78px; display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center; gap: 20px;
}
.brand {
  font-family: var(--serif); font-size: clamp(1.35rem, 3vw, 2rem);
  letter-spacing: .02em; line-height: 1;
}
.brand small {
  display: block; margin-top: 7px; font: 600 .62rem/1 var(--sans);
  letter-spacing: .19em; text-transform: uppercase; color: var(--muted);
}
.main-nav { display: flex; gap: 22px; align-items: center; }
.main-nav a {
  font-size: .82rem; font-weight: 700; color: var(--muted);
  transition: color .2s ease;
}
.main-nav a:hover { color: var(--accent); }
.header-actions { display: flex; justify-content: flex-end; gap: 8px; }
.icon-btn {
  border: 1px solid var(--line); background: var(--card); color: var(--ink);
  width: 40px; height: 40px; border-radius: 999px;
  display: grid; place-items: center; cursor: pointer;
}
.icon {
  width: 18px; height: 18px; fill: none; stroke: currentColor;
  stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round;
}
/* Moon in light mode, sun in dark mode; menu and close swap with the menu state. */
.icon-sun, .icon-close,
html.dark .icon-moon, #menuToggle[aria-expanded='true'] .icon-menu { display: none; }
html.dark .icon-sun, #menuToggle[aria-expanded='true'] .icon-close { display: block; }
.mobile-menu-btn { display: none; }
.mobile-nav { display: none; }
.mobile-nav a { font-weight: 700; font-size: .95rem; }

/* Masthead */
.masthead { padding: 74px 0 54px; border-bottom: 1px solid var(--line); }
.masthead-grid {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(200px, 260px);
  gap: clamp(32px, 5vw, 72px); align-items: end;
}
.eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--accent); font-size: .74rem; font-weight: 800;
  letter-spacing: .16em; text-transform: uppercase;
}
.eyebrow:before { content: ''; width: 26px; height: 2px; background: currentColor; }
.masthead-lead h1 {
  margin: 20px 0 0; max-width: 15ch;
  font-family: var(--serif); font-size: clamp(3.1rem, 8.5vw, 7.8rem);
  line-height: .88; letter-spacing: -.035em; font-weight: 400;
}
.masthead-mark {
  display: block; width: 64px; height: 3px; margin: 30px 0 26px;
  background: var(--accent); border-radius: 2px;
}
.masthead-lead p {
  max-width: 44ch; margin: 0; color: var(--muted);
  font: 500 clamp(1rem, 2vw, 1.28rem)/1.7 var(--sans);
}
.masthead-lead .masthead-tagline { display: none; }
.masthead-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 26px; }
/* Pill buttons. .btn is the shared name (pages use it); .masthead-btn stays
   as an alias so existing markup keeps working. */
.btn, .masthead-btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 44px; border: 1px solid var(--line); border-radius: 999px;
  padding: 10px 17px; background: var(--card); color: var(--ink);
  font: 800 .8rem/1.2 var(--sans); text-decoration: none; cursor: pointer;
}
.btn:hover, .masthead-btn:hover { border-color: var(--accent); color: var(--accent); }
.btn--solid, .masthead-btn--solid { border-color: var(--accent-solid); background: var(--accent-solid); color: #fff; }
.btn--solid:hover, .masthead-btn--solid:hover { color: #fff; filter: brightness(1.06); }
.btn-row { display: flex; flex-wrap: wrap; gap: 10px; }
.masthead-rail {
  display: flex; flex-direction: column;
  border-top: 1px solid var(--line);
}
.rail-item {
  position: relative; padding: 15px 0 15px 18px;
  border-bottom: 1px solid var(--line);
  font-size: .8rem; font-weight: 700; line-height: 1.4;
  letter-spacing: .01em; color: var(--muted);
}
.rail-item:before {
  content: ''; position: absolute; left: 0; top: 20px;
  width: 7px; height: 7px; border-radius: 999px; background: var(--accent);
}
/* Masthead entrance */
@keyframes riseIn {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}
.masthead-lead .eyebrow,
.masthead-lead h1,
.masthead-mark,
.masthead-lead p,
.masthead-actions,
.masthead-rail .rail-item {
  animation: riseIn .6s cubic-bezier(.22, .61, .36, 1) both;
}
.masthead-lead .eyebrow { animation-delay: 0s; }
.masthead-lead h1 { animation-delay: .07s; }
.masthead-mark { animation-delay: .16s; }
.masthead-lead p { animation-delay: .22s; }
.masthead-actions { animation-delay: .26s; }
.masthead-rail .rail-item:nth-child(1) { animation-delay: .28s; }
.masthead-rail .rail-item:nth-child(2) { animation-delay: .35s; }
.masthead-rail .rail-item:nth-child(3) { animation-delay: .42s; }

/* Index / cards */
.index-section { padding: 55px 0 80px; }
.section-bar {
  display: flex; align-items: end; justify-content: space-between;
  gap: 20px; margin-bottom: 24px;
}
.section-bar h2 { margin: 0; font: 400 clamp(2rem, 5vw, 3.6rem)/1 var(--serif); }
.section-bar span { color: var(--muted); font-size: .82rem; font-weight: 700; }
.posts-grid {
  display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 26px;
}
.post-card {
  min-width: 0; border-top: 1px solid var(--line); padding-top: 16px;
}
.post-card:first-child {
  grid-column: 1 / -1; display: grid; grid-template-columns: 1.45fr .9fr;
  gap: 42px; padding: 0 0 48px; border-top: 0; border-bottom: 1px solid var(--line);
}
.post-card-media {
  display: block; aspect-ratio: 16 / 10; overflow: hidden;
  border-radius: 2px; background:
    radial-gradient(circle at 20% 20%, rgba(178,138,74,.25), transparent 35%),
    linear-gradient(135deg, var(--paper-2), var(--line));
}
.post-card:first-child .post-card-media { aspect-ratio: 16 / 10; order: 2; }
.post-card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.post-card:hover .post-card-media img { transform: scale(1.025); }
.post-card-content { padding-top: 16px; }
.post-card:first-child .post-card-content { display: flex; flex-direction: column; justify-content: center; padding: 18px 0; }
.post-labels { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.post-label {
  color: var(--accent); font-size: .7rem; font-weight: 800;
  letter-spacing: .1em; text-transform: uppercase;
}
.post-card h2 {
  margin: 0 0 12px; font: 400 clamp(1.65rem, 2.6vw, 2.35rem)/1.03 var(--serif);
  letter-spacing: -.012em;
}
.post-card:first-child h2 { font-size: clamp(2.6rem, 5.5vw, 5.7rem); line-height: .93; }
.post-card h2 a:hover { color: var(--accent); }
.post-snippet { margin: 0 0 18px; color: var(--muted); font-size: .92rem; line-height: 1.7; }
.post-card:first-child .post-snippet { max-width: 620px; font-size: 1.04rem; }
.post-meta {
  margin-top: auto; display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  color: var(--muted); font-size: .74rem; font-weight: 600;
}
.dot { display: inline-flex; align-items: center; gap: 8px; }
.dot:before {
  content: '';
  width: 3px;
  height: 3px;
  flex: 0 0 3px;
  border-radius: 50%;
  background: currentColor;
}
.read-link { color: var(--ink); font-weight: 800; }
.read-link:hover { color: var(--accent); }
.post-audio-flag {
  display: inline-flex; align-items: center; min-height: 20px;
  border: 1px solid var(--line); border-radius: 999px; padding: 1px 8px;
  color: var(--muted); font-size: .62rem; font-weight: 800;
  letter-spacing: .08em; text-transform: uppercase; white-space: nowrap;
}

/* Pagination */
.blog-pagination { display: flex; justify-content: space-between; gap: 12px; margin-top: 48px; }
.blog-pagination a {
  border: 1px solid var(--line); background: var(--card); padding: 12px 17px;
  border-radius: 999px; font-size: .82rem; font-weight: 800;
}
.blog-pagination a:hover { border-color: var(--accent); color: var(--accent); }

/* Article */
.article-shell { padding: 64px 0 100px; }
.article-header { width: min(calc(100% - 40px), 1080px); margin: 0 auto 38px; text-align: center; }
.article-kicker { color: var(--accent); font-size: .72rem; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }
.article-title {
  margin: 16px auto 20px; max-width: 1020px;
  font: 400 clamp(3rem, 8vw, 7.2rem)/.93 var(--serif); letter-spacing: -.035em;
}
/* Standfirst: the post's Search Description, shown under the title. */
.article-dek {
  max-width: 34em; margin: 0 auto 22px; color: var(--muted);
  font: 400 clamp(1.08rem, 1.7vw, 1.3rem)/1.55 Georgia, 'Times New Roman', serif;
  text-wrap: balance;
}
.article-byline {
  display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 9px;
  color: var(--muted); font-size: .78rem; font-weight: 650;
}
/* A listened-to paper: small chip in the byline that jumps to the player. */
.byline-audio {
  display: inline-flex; align-items: center; gap: 6px; min-height: 30px;
  border: 1px solid var(--line); border-radius: 999px; padding: 4px 11px 4px 9px;
  background: var(--card); color: var(--accent); font-weight: 750;
}
.byline-audio:hover { border-color: var(--accent); }
.byline-author:hover strong { color: var(--accent); }
.byline-audio svg {
  width: 14px; height: 14px; fill: none; stroke: currentColor;
  stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;
}
.article-hero { width: min(calc(100% - 40px), 900px); margin: 34px auto 48px; }
.article-hero img {
  width: 100%; height: auto; max-height: 560px; aspect-ratio: 16 / 9; object-fit: cover;
  background: var(--paper-2);
}
/* The lead photo's credit, moved here from the post body by the script. */
.article-hero-caption {
  max-width: 72ch; margin: 10px 0 0; color: var(--muted);
  font: .74rem/1.55 var(--sans); overflow-wrap: anywhere;
}
.article-hero-caption a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }
.article-hero-caption a:hover { color: var(--accent); }
/* Three tracks: contents rail, reading column, share rail. The 1160px frame
   lets the column reach the full 760px measure, matching the blocks below it. */
.article-layout {
  width: min(calc(100% - 40px), 1160px); margin: 0 auto;
  display: grid; grid-template-columns: 160px minmax(0,var(--reading)) 160px;
  justify-content: center; gap: 40px;
}
/* Between tablet and wide desktop, slim the rails instead of the column. */
@media (min-width: 981px) and (max-width: 1216px) {
  .article-layout { grid-template-columns: 120px minmax(0,var(--reading)) 120px; gap: 28px; }
}
.article-aside { position: relative; }
.sticky-box { position: sticky; top: 105px; }
.aside-title { margin: 0 0 12px; color: var(--muted); font-size: .66rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.toc { display: grid; gap: 2px; border-left: 1px solid var(--line); }
.toc a {
  display: block; margin-left: -1px; padding: 4px 0 4px 12px;
  border-left: 2px solid transparent;
  color: var(--muted); font-size: .74rem; line-height: 1.35;
}
.toc a.toc-sub { padding-left: 22px; }
.toc a:hover { color: var(--accent); }
.toc a.is-active { border-left-color: var(--accent); color: var(--ink); font-weight: 700; }
.toc.toc--empty { border-left: 0; }
.toc-empty { color: var(--muted); font-size: .72rem; line-height: 1.4; }
/* Contents for phones and tablets, where the rail is hidden. */
.toc-mobile { display: none; }
.share-stack { display: grid; gap: 8px; }
.share-btn {
  border: 1px solid var(--line); background: var(--card); color: var(--ink);
  border-radius: 999px; padding: 9px 10px; text-align: center; font-size: .7rem; font-weight: 800;
  cursor: pointer;
}
.share-btn:hover { color: var(--accent); border-color: var(--accent); }
/* Share row under the author box, for screens without the share rail. */
.share-row { display: none; }

.article-main { min-width: 0; }
/* Audio edition: one strip of chrome above the player, which carries its own title. */
.paper-audio {
  margin: 0 0 32px; padding: 12px 0 18px;
  border-top: 3px solid var(--accent); border-bottom: 1px solid var(--line);
  scroll-margin-top: 100px;
}
.paper-audio[hidden] { display: none; }
.paper-audio-heading {
  display: flex; flex-wrap: wrap; align-items: baseline;
  justify-content: space-between; gap: 4px 16px; margin-bottom: 12px;
}
.paper-audio-title {
  margin: 0; color: var(--accent); font: 800 .7rem/1.5 var(--sans);
  letter-spacing: .14em; text-transform: uppercase;
}
.paper-audio-note { color: var(--muted); font-weight: 650; letter-spacing: .02em; text-transform: none; }
.paper-audio-note:before { content: '\00b7'; margin: 0 8px; color: var(--muted); }
.paper-audio-link {
  color: var(--accent); font-size: .74rem; font-weight: 700;
  text-decoration: underline; text-underline-offset: 3px;
}
.paper-audio-player > iframe {
  display: block; width: 100% !important; max-width: 100%;
  min-height: 166px; border: 0; border-radius: 3px;
}
/* AZ Studio player block. Posts may still carry their own copy of these
   styles; the extra .post-content / .paper-audio-player scope wins over it. */
.post-content .pwavwe-audio-embed,
.paper-audio-player .pwavwe-audio-embed { --pwavwe-audio-h: 156px; margin: 1.75em 0; max-width: 760px; }
@media (max-width: 576px) {
  .post-content .pwavwe-audio-embed,
  .paper-audio-player .pwavwe-audio-embed { --pwavwe-audio-h: 224px; }
}
@media (max-width: 312px) {
  .post-content .pwavwe-audio-embed,
  .paper-audio-player .pwavwe-audio-embed { --pwavwe-audio-h: 264px; }
}
.post-content .pwavwe-audio-embed iframe,
.paper-audio-player .pwavwe-audio-embed iframe {
  display: block; width: 100%; height: var(--pwavwe-audio-h);
  border: 0; border-radius: 12px; overflow: hidden;
}
.post-content .pwavwe-audio-embed p { margin: .45em 0 0; }
.post-content .pwavwe-audio-open {
  font-family: var(--sans); font-size: .78em; color: inherit; opacity: .68;
  text-decoration: underline; text-underline-offset: .2em;
}
.post-content .pwavwe-audio-open:hover,
.post-content .pwavwe-audio-open:focus { opacity: 1; }
/* Inside the panel, the heading's Open audio link replaces the block's own. */
.paper-audio-player .pwavwe-audio-embed { margin: 0 !important; max-width: none !important; }
.paper-audio-player .pwavwe-audio-embed p { display: none; }
.paper-audio-credit {
  margin-top: 10px; color: var(--muted); font: .7rem/1.5 var(--sans);
  overflow-wrap: anywhere;
}
.paper-audio-credit a { color: inherit; text-decoration: underline; text-underline-offset: 2px; }

.post-content {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: clamp(1.08rem, 1.7vw, 1.25rem); line-height: 1.86;
  overflow-wrap: anywhere;
}
.post-content > *:first-child { margin-top: 0; }
.post-content p { margin: 0 0 1.5em; }
/* Opening paragraph, marked by the script. */
.post-content p.lede { font-size: 1.08em; line-height: 1.8; }
/* Headings sit on one scale with the body (about 1.5x), not 3x. */
.post-content h2, .post-content h3, .post-content h4 {
  font-family: var(--serif); font-weight: 400; line-height: 1.12; letter-spacing: -.01em;
  scroll-margin-top: 110px; text-wrap: balance;
}
.post-content h2 { margin: 2.2em 0 .6em; font-size: clamp(1.7rem, 2.4vw, 2.25rem); }
.post-content h3 { margin: 1.9em 0 .55em; font-size: clamp(1.35rem, 1.9vw, 1.65rem); }
.post-content h4 { margin: 1.7em 0 .5em; font-size: 1.15em; }
.post-content a { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.post-content blockquote {
  margin: 2em 0; padding: .1em 0 .1em 1em; border-left: 3px solid var(--accent);
  font-family: var(--serif); font-size: clamp(1.3rem, 2.2vw, 1.7rem); line-height: 1.3;
}
.post-content blockquote p:last-child { margin-bottom: 0; }
.post-content img { margin: 2em auto; max-height: 780px; object-fit: contain; }
.post-content figure { margin: 2em 0; }
.post-content figcaption { color: var(--muted); font: .75rem/1.5 var(--sans); text-align: center; }
.post-content ul, .post-content ol { padding-left: 1.25em; margin: 0 0 1.5em; }
.post-content li { margin-bottom: .55em; }
.post-content hr { border: 0; border-top: 1px solid var(--line); margin: 3em 0; }
.post-content pre {
  overflow: auto; padding: 18px; background: #0e0e0e; color: #f1f1f1; border-radius: 6px;
  font: .9rem/1.6 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.post-content code { font-size: .88em; }
/* Related case study at the end of a paper. The post adds one line of HTML,
   <p class="case-study-link"><a href="https://pwavwe.com/work/comitia">…</a></p>
   (see CASE-STUDY-LINKS.md), and the script fills in the project's summary. */
.post-content .case-study-link { margin: 2.6em 0 0; }
.post-content .case-study-link a {
  display: block; padding: 18px 20px 20px; border: 1px solid var(--line);
  border-top: 3px solid var(--accent); border-radius: 0 0 8px 8px;
  background: var(--card); color: var(--ink); text-decoration: none;
  font: 750 1rem/1.45 var(--sans);
}
.post-content .case-study-link a:hover { border-color: var(--accent); }
.case-study-link span { display: block; }
.case-study-link .case-study-kicker {
  margin-bottom: 6px; color: var(--accent); font-size: .68rem; font-weight: 800;
  letter-spacing: .08em; text-transform: uppercase;
}
.case-study-link .case-study-title { font: 400 1.45rem/1.15 var(--serif); }
.case-study-link .case-study-summary {
  margin-top: 6px; color: var(--muted); font-size: .9rem; font-weight: 450; line-height: 1.55;
}
.case-study-link .case-study-cta { margin-top: 12px; color: var(--accent); font-size: .82rem; }
.article-footer {
  width: min(calc(100% - 40px), var(--reading)); margin: 48px auto 0;
  border-top: 1px solid var(--line); padding-top: 26px;
}
.author-box {
  display: grid; grid-template-columns: auto 1fr; gap: 18px; align-items: start;
  background: var(--card); border: 1px solid var(--line); padding: 24px;
}
.author-photo {
  width: 72px; height: 72px; border-radius: 50%; object-fit: cover; background: var(--paper-2);
}
.author-box .author-name { margin: 0 0 6px; font: 400 1.4rem/1 var(--serif); }
.author-box p { margin: 0; color: var(--muted); font-size: .86rem; line-height: 1.6; }
.author-box .author-links { display: flex; flex-wrap: wrap; gap: 6px 20px; margin-top: 12px; }
.author-links a { color: var(--accent); font-weight: 750; }
.author-links a:hover { text-decoration: underline; text-underline-offset: 3px; }
/* Phones: photo above the note, so the bio gets the card's full width. */
@media (max-width: 640px) {
  .author-box { grid-template-columns: 1fr; gap: 14px; }
  .author-photo { width: 64px; height: 64px; }
}
/* On a paper, the author note and the newsletter form share one card. */
body.item .paper-end {
  border: 1px solid var(--line); border-radius: 8px; background: var(--card); overflow: hidden;
}
body.item .paper-end .author-box { border: 0; background: none; }

/* Comments */
.comments-wrap {
  width: min(calc(100% - 40px), var(--reading)); margin: 54px auto 0;
  border-top: 1px solid var(--line); padding-top: 30px;
}
.comments-gate { border: 1px solid var(--line); border-radius: 8px; background: var(--card); }
.comments-gate summary {
  display: flex; align-items: center; justify-content: space-between; gap: 18px;
  padding: 18px 20px; cursor: pointer; color: var(--ink); font-weight: 800;
}
.comments-gate summary::marker { color: var(--accent); }
.comments-gate summary span { color: var(--muted); font-size: .72rem; font-weight: 650; }
.comments-gate[open] summary { border-bottom: 1px solid var(--line); }
.comments-mount { padding: 22px 20px; }
.comments-wrap .comments, .comments-wrap .comments-content, .comments-wrap .comment-thread {
  margin: 0;
}
.comments-wrap > .comments > h4,
.comments-wrap .comments > h4:first-child,
.comments-wrap .comments-title {
  margin: 0 0 28px;
  font: 400 clamp(2.05rem, 4vw, 3.1rem)/1.02 var(--serif);
  letter-spacing: -.015em;
  color: var(--ink);
}
.comments-wrap .comments-content ol,
.comments-wrap .comment-thread ol {
  list-style: none;
  margin: 0;
  padding: 0;
}
.comments-wrap .comments-content li,
.comments-wrap .comment-thread li {
  margin: 0;
  padding: 0;
}
.comments-wrap .comments-content > ol > li.comment,
.comments-wrap .comment-thread > ol > li.comment,
.comments-wrap .comment-thread ol > li.comment {
  margin-bottom: 22px;
}
.comments-wrap .avatar-image-container {
  float: left;
  width: 44px;
  height: 44px;
  margin: 4px 14px 0 0;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--paper-2);
  overflow: hidden;
}
.comments-wrap .avatar-image-container img {
  width: 100%;
  height: 100%;
  margin: 0;
  object-fit: cover;
  border-radius: inherit;
}
.comments-wrap .comment-block {
  min-height: 54px;
  margin-left: 58px;
  border: 1px solid var(--line);
  background: var(--card);
  padding: 18px 20px 16px;
  box-shadow: 0 12px 30px rgba(23, 23, 23, .045);
}
.comments-wrap .comment-header {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0 .35rem;
  margin: 0 0 12px;
  color: var(--muted);
  font: 700 .76rem/1.45 var(--sans);
}
.comments-wrap .comment-header cite,
.comments-wrap .comment-header .user {
  color: var(--ink);
  font-style: normal;
  font-weight: 800;
}
.comments-wrap .comment-header a {
  color: inherit;
}
.comments-wrap .comment-header .datetime:before {
  content: '·';
  margin: 0 .55rem 0 .2rem;
  color: var(--line);
}
.comments-wrap .comment-content {
  margin: 0;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 1.02rem;
  line-height: 1.75;
}
.comments-wrap .comment-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin: 16px 0 0;
  font: 800 .72rem/1 var(--sans);
}
.comments-wrap .comment-actions .item-control {
  display: inline-flex;
}
.comments-wrap a {
  color: var(--accent);
}
.comments-wrap .comment-actions a,
.comments-wrap .comment-reply a,
.comments-wrap .continue a,
.comments-wrap .loadmore a {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 10px;
  background: color-mix(in srgb, var(--card) 86%, var(--paper-2));
  color: var(--accent);
  font: 800 .72rem/1 var(--sans);
}
.comments-wrap .comment-actions a:hover,
.comments-wrap .comment-reply a:hover,
.comments-wrap .continue a:hover,
.comments-wrap .loadmore a:hover {
  border-color: var(--accent-solid);
  background: var(--accent-solid);
  color: #fff;
}
.comments-wrap .comment-replies {
  clear: both;
  margin: 18px 0 0 58px;
  border-left: 2px solid color-mix(in srgb, var(--accent) 24%, var(--line));
  padding: 18px 0 0 22px;
}
.comments-wrap .comment-replies .comment {
  margin-bottom: 16px;
}
.comments-wrap .comment-replies .comment-block {
  background: color-mix(in srgb, var(--card) 82%, var(--paper-2));
  box-shadow: none;
}
.comments-wrap .comment-replies h4,
.comments-wrap .thread-toggle {
  margin: 0 0 14px;
}
.comments-wrap .comment-replies h4,
.comments-wrap .thread-count,
.comments-wrap .thread-count a {
  color: var(--muted);
  font: 800 .7rem/1 var(--sans);
  letter-spacing: .12em;
  text-transform: uppercase;
}
.comments-wrap .thread-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
}
.comments-wrap .thread-chrome {
  margin: 0;
}
.comments-wrap .comment-replybox-single,
.comments-wrap .comment-replybox-thread {
  clear: both;
  margin: 16px 0 0 58px;
}
.comments-wrap .comment-footer {
  margin: 28px 0 0;
}
.comments-wrap .comment-footer a {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  border: 1px solid var(--accent-solid);
  border-radius: 999px;
  padding: 9px 14px;
  background: var(--accent-solid);
  color: #fff;
  font: 800 .78rem/1 var(--sans);
}
.comments-wrap .comment-form {
  margin-top: 18px;
  border: 1px solid var(--line);
  background: var(--card);
  padding: 16px;
}
.comments-wrap iframe {
  width: 100% !important;
  max-width: 100%;
}

@media (max-width: 640px) {
  .comments-wrap {
    width: min(calc(100% - 28px), 100%);
    margin-top: 42px;
    padding-top: 24px;
  }
  .comments-wrap .comment-block,
  .comments-wrap .comment-replybox-single,
  .comments-wrap .comment-replybox-thread {
    margin-left: 52px;
  }
  .comments-wrap .comment-replies {
    margin-left: 18px;
    padding-left: 16px;
  }
  .comments-wrap .comment-block {
    padding: 16px;
  }
}

/* Search overlay */
.search-overlay {
  display: none; position: fixed; inset: 0; z-index: 1500;
  background: color-mix(in srgb, var(--paper) 96%, transparent); backdrop-filter: blur(14px);
}
.search-overlay.open { display: grid; place-items: start center; padding: 17vh 20px 30px; }
.search-box { width: min(720px,100%); }
.search-box label { display: block; margin-bottom: 12px; color: var(--muted); font-size: .72rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.search-row { display: grid; grid-template-columns: 1fr auto; gap: 10px; }
.search-row input {
  width: 100%; border: 0; border-bottom: 2px solid var(--ink); background: transparent;
  color: var(--ink); padding: 12px 4px; outline: none; font: 400 clamp(1.6rem,5vw,3.4rem)/1.1 var(--serif);
}
.search-row button { border: 0; background: var(--accent-solid); color: #fff; padding: 0 18px; cursor: pointer; font-weight: 800; }
.search-close { margin-top: 18px; border: 0; background: none; color: var(--muted); padding: 0; cursor: pointer; }

/* Footer */
.site-footer { border-top: 1px solid var(--line); padding: 46px 0 56px; }
.footer-grid { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1.4fr; gap: 34px; }
.footer-brand { font: 400 2rem/1 var(--serif); }
.footer-copy { margin-top: 12px; max-width: 460px; color: var(--muted); font-size: .86rem; line-height: 1.65; }
.footer-heading { margin-bottom: 12px; font-size: .7rem; font-weight: 800; color: var(--muted); letter-spacing: .12em; text-transform: uppercase; }
.footer-links { display: grid; gap: 9px; font-size: .85rem; font-weight: 650; }
.footer-links a:hover { color: var(--accent); }
.footer-bottom { margin-top: 38px; padding-top: 18px; border-top: 1px solid var(--line); color: var(--muted); font-size: .72rem; }
.footer-sub-copy { margin: 0 0 14px; max-width: 320px; color: var(--muted); font-size: .85rem; line-height: 1.6; }
.footer-sub-form { display: flex; gap: 8px; max-width: 340px; margin: 0; }
.footer-sub-form .subscribe-input { padding: 10px 14px; font-size: .88rem; }
.footer-sub-form .subscribe-btn { padding: 10px 16px; font-size: .78rem; }
.footer-subscribe .subscribe-note { min-height: 0; margin: 10px 0 0; font-size: .8rem; }
@media (max-width: 420px) {
  .footer-sub-form { flex-direction: column; }
  .footer-sub-form .subscribe-btn { width: 100%; }
}

/* Blogger cleanup */
.widget, .widget-content { margin: 0; }
.status-msg-wrap, .feed-links { display: none; }

/* Sub-mastheads for label / search / archive pages (no more repeated H1) */
.masthead--sub { padding: 54px 0 34px; }
.masthead-sub-title {
  margin: 14px 0 10px; font-family: var(--serif); font-weight: 400;
  font-size: clamp(2.6rem, 7vw, 5rem); line-height: .95; letter-spacing: -.03em;
}
.masthead--sub p { max-width: 620px; margin: 0; color: var(--muted); font: 500 1rem/1.6 var(--sans); }
.masthead--sub + main .index-section { padding-top: 40px; }

/* Search or label page with nothing to list */
.empty-state { padding: 6px 0 20px; }
.empty-state p { max-width: 46ch; margin: 0 0 18px; color: var(--muted); font-size: 1rem; line-height: 1.6; }

/* =========================================================
   Pages: Start Here, All papers, About, Contact, Privacy.
   Page bodies build on these shared pieces. The prose defaults
   are wrapped in :where() so they carry no class weight, and
   a page's own classes always win over them.
   ========================================================= */
.page-shell { --page-max: 760px; padding: 54px 0 90px; }
.page-shell:has(.page--wide) { --page-max: 960px; }
.page-header, .page-content { width: min(calc(100% - 40px), var(--page-max)); margin: 0 auto; }
.page-header { margin-bottom: 34px; padding-bottom: 24px; border-bottom: 1px solid var(--line); }
.page-title { margin: 0; font: 400 clamp(2.6rem, 7vw, 4.6rem)/.95 var(--serif); letter-spacing: -.03em; }
.page-content { color: var(--ink); font-size: 1.02rem; line-height: 1.8; overflow-wrap: anywhere; }
.page-content > :first-child { margin-top: 0; }
:where(.page-content) p { margin: 0 0 1.15em; }
:where(.page-content) h2 { margin: 2.1em 0 .5em; font: 400 clamp(1.5rem, 3vw, 2rem)/1.15 var(--serif); letter-spacing: -.01em; }
:where(.page-content) h3 { margin: 1.8em 0 .5em; font: 400 1.3rem/1.2 var(--serif); }
:where(.page-content) ul, :where(.page-content) ol { margin: 0 0 1.2em; padding-left: 1.25em; }
:where(.page-content) li { margin-bottom: .45em; }
:where(.page-content) a:not([class]) {
  color: var(--ink); text-decoration: underline; text-decoration-thickness: 1px;
  text-decoration-color: color-mix(in srgb, var(--accent) 60%, transparent); text-underline-offset: 3px;
}
:where(.page-content) a:not([class]):hover { color: var(--accent); text-decoration-color: currentColor; }
.page-lede { margin: 0 0 1em; color: var(--ink); font: 400 clamp(1.35rem, 3vw, 1.9rem)/1.3 var(--serif); }
.page-eyebrow {
  display: block; color: var(--muted); font-size: .7rem; font-weight: 800;
  letter-spacing: .12em; text-transform: uppercase;
}
.page-card { border: 1px solid var(--line); border-radius: 6px; background: var(--card); padding: 22px 24px; }
.page-list { list-style: none; margin: 0; padding: 0; }
.page-list > li { margin: 0; }
/* Every page ends with a way onward. */
.page-next { margin-top: 2.4em; padding-top: 22px; border-top: 1px solid var(--line); }
.page-next p { color: var(--muted); }
@media (max-width: 640px) {
  .page-shell { padding: 36px 0 70px; }
  .page-header, .page-content { width: min(calc(100% - 28px), var(--page-max)); }
  .page-header { margin-bottom: 26px; padding-bottom: 18px; }
}

/* 404 */
.error-wrap { text-align: center; padding: 60px 0 40px; }
.error-title { margin: 14px 0 12px; font: 400 clamp(2.4rem, 6vw, 4.4rem)/1 var(--serif); }
.error-wrap p { max-width: 520px; margin: 0 auto 22px; color: var(--muted); line-height: 1.6; }

/* Hide the body's own lead image so it doesn't duplicate the theme hero. A lead
   figure keeps its caption, so photo credits stay visible without JavaScript;
   the script then moves the caption under the hero and hides the figure. */
.post-content > .separator:first-child,
.post-content > img:first-child,
.post-content > figure:first-child:has(img) > :not(figcaption),
.post-content > p:first-child:has(> img:only-child),
.post-content > p:first-child:has(> a:only-child > img:only-child) { display: none; }
.post-content > figure:first-child:has(img) { margin-top: 0; }

/* Newer / older paper: quiet text links under Continue reading */
.post-nav {
  width: min(calc(100% - 40px), var(--reading)); margin: 28px auto 0;
  display: flex; justify-content: space-between; gap: 14px;
}
.post-nav-link {
  display: inline-flex; align-items: center; min-height: 44px;
  color: var(--muted); font-size: .82rem; font-weight: 800;
}
.post-nav-link:hover { color: var(--accent); }
.post-nav-link--next { margin-left: auto; }

/* Continue reading */
.related {
  width: min(calc(100% - 40px), var(--reading)); margin: 46px auto 0;
  border-top: 1px solid var(--line); padding-top: 26px;
}
.related-head { margin: 0 0 18px; font: 400 1.6rem/1 var(--serif); }
.related-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 18px; }
.related-card { display: grid; gap: 10px; min-width: 0; }
.related-thumb {
  display: block; aspect-ratio: 16/10; border-radius: 2px;
  background-size: cover; background-position: center; background-color: var(--paper-2);
}
.related-thumb--empty { background: linear-gradient(135deg, var(--paper-2), var(--line)); }
.related-title { font: 400 1.05rem/1.2 var(--serif); }
.related-card:hover .related-title { color: var(--accent); }

/* Subscribe: the lower half of the paper-end card */
.subscribe { padding: 20px 24px 22px; border-top: 1px solid var(--line); }
.subscribe-title { margin: 0 0 4px; font: 400 clamp(1.3rem, 2.4vw, 1.55rem)/1.15 var(--serif); }
.subscribe-copy { margin: 0 0 14px; color: var(--muted); font-size: .86rem; line-height: 1.55; }
.subscribe .subscribe-form { max-width: 520px; margin: 0; }
.subscribe .subscribe-note { min-height: 0; margin-top: 10px; }
/* Collapsed while empty but kept in the accessibility tree, so the live
   region still announces the result. */
.subscribe .subscribe-note:empty { margin-top: 0; }
/* After a successful sign-up the form gives way to the confirmation. */
.subscribe-form[hidden] { display: none; }
.subscribe-note--ok { color: var(--ink); font-weight: 650; }
.subscribe-note:focus { outline: none; }
/* Papers carry their own form, so the footer doesn't repeat it there. */
body.item .footer-subscribe { display: none; }
@media (min-width: 981px) {
  body.item .footer-grid { grid-template-columns: 1.4fr 1fr 1fr; }
}
.subscribe-btn {
  display: inline-block; background: var(--accent-solid); color: #fff; font-weight: 800;
  font-size: .82rem; padding: 12px 22px; border-radius: 999px;
}
.subscribe-btn:hover { filter: brightness(1.06); }

/* Newsletter form (Firebase Firestore), dressed in the theme's palette */
.subscribe-form { display: flex; gap: 10px; max-width: 460px; margin: 4px auto 0; }
.subscribe-input {
  flex: 1; min-width: 0; border: 1px solid var(--line); background: var(--paper);
  color: var(--ink); border-radius: 999px; padding: 12px 18px; outline: none;
  font: 500 .95rem var(--sans); text-align: left;
}
.subscribe-input:focus { border-color: var(--accent); }
.subscribe-input::placeholder { color: var(--muted); opacity: 1; }
.subscribe-form .subscribe-btn { border: 0; cursor: pointer; white-space: nowrap; }
.subscribe-note {
  min-height: 1.2em; margin: 14px 0 0; color: var(--muted);
  font-size: .85rem; line-height: 1.5;
}
.subscribe-privacy { margin: 9px 0 0; color: var(--muted); font-size: .72rem; line-height: 1.5; }
.subscribe-privacy a { color: var(--ink); text-decoration: underline; text-underline-offset: 2px; }

@media (max-width: 480px) {
  .subscribe-form { flex-direction: column; }
  .subscribe-form .subscribe-btn { width: 100%; }
}

@media (max-width: 640px) {
  /* Compact rows on phones: thumbnail left, title right. */
  .related-grid { grid-template-columns: 1fr; gap: 14px; }
  .related-card { grid-template-columns: 112px minmax(0, 1fr); align-items: center; gap: 14px; }
  .related-thumb { aspect-ratio: 4 / 3; }
}

@media (max-width: 980px) {
  .header-inner { grid-template-columns: 1fr auto; }
  .main-nav { display: none; }
  .mobile-menu-btn { display: grid; }
  .mobile-nav {
    position: fixed; top: 86px; right: max(14px, env(safe-area-inset-right));
    z-index: 1001; display: grid; gap: 12px;
    width: min(320px, calc(100% - 28px)); max-height: calc(100dvh - 100px);
    overflow-y: auto; border: 1px solid var(--line); border-radius: 10px;
    padding: 14px; background: var(--card); box-shadow: var(--shadow);
    opacity: 0; pointer-events: none; visibility: hidden;
    transform: translateX(calc(100% + 28px));
    transition: opacity .18s ease, transform .18s ease, visibility 0s linear .18s;
  }
  .mobile-nav.open {
    opacity: 1; pointer-events: auto; visibility: visible; transform: translateX(0);
    transition-delay: 0s;
  }
  .posts-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .post-card:first-child { grid-template-columns: 1fr; gap: 12px; }
  .post-card:first-child .post-card-media { order: 0; }
  .article-layout { grid-template-columns: minmax(0,var(--reading)); }
  .article-aside { display: none; }
  .toc-mobile:not([hidden]) {
    display: block; margin: 0 0 30px;
    border: 1px solid var(--line); border-radius: 8px; background: var(--card);
  }
  .toc-mobile summary {
    display: flex; align-items: center; justify-content: space-between; gap: 18px;
    padding: 14px 18px; cursor: pointer; list-style: none;
    color: var(--ink); font-size: .88rem; font-weight: 800;
  }
  .toc-mobile summary::-webkit-details-marker { display: none; }
  .toc-mobile summary span { color: var(--muted); font-size: .72rem; font-weight: 650; }
  .toc-mobile summary span:after { content: ' +'; color: var(--accent); font-weight: 800; }
  .toc-mobile[open] summary span:after { content: ' \2013'; }
  .toc-mobile[open] summary { border-bottom: 1px solid var(--line); }
  .toc-mobile .toc { margin: 14px 18px 16px; }
  .toc-mobile .toc a { padding-top: 7px; padding-bottom: 7px; font-size: .9rem; }
  .share-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 18px; }
  .share-row-label {
    margin-right: 4px; color: var(--muted); font-size: .66rem; font-weight: 800;
    letter-spacing: .12em; text-transform: uppercase;
  }
  .share-row .share-btn { display: inline-flex; align-items: center; min-height: 44px; padding: 10px 15px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid > :first-child { grid-column: 1 / -1; }
}

@media (max-width: 640px) {
  .wrap { width: min(calc(100% - 28px), var(--max)); }
  .header-inner { min-height: 66px; }
  .mobile-nav { top: 74px; }
  .brand { font-size: 1.35rem; }
  .brand small { display: none; }
  .icon-btn { width: 36px; height: 36px; }
  /* Phones: get to the first paper within one screen. */
  .masthead { padding: 28px 0 24px; }
  .masthead h1 { font-size: clamp(2.6rem, 12vw, 4rem); }
  .masthead-grid { grid-template-columns: 1fr; gap: 30px; align-items: start; }
  .masthead-mark { margin: 18px 0 16px; }
  .masthead-lead p { font-size: 1rem; line-height: 1.6; }
  .masthead-lead .masthead-tagline {
    display: block; margin-top: 12px; font-size: .78rem; font-weight: 700;
    line-height: 1.5; letter-spacing: .01em;
  }
  .masthead-actions { margin-top: 20px; }
  .masthead-rail { display: none; }
  .index-section { padding: 34px 0 64px; }
  .masthead--sub + main .index-section { padding-top: 28px; }
  .section-bar { margin-bottom: 18px; }
  .section-bar span { display: none; }
  .posts-grid { grid-template-columns: 1fr; gap: 34px; }
  .post-card:first-child { padding-bottom: 36px; }
  .post-card:first-child h2 { font-size: clamp(2.5rem, 12vw, 4.4rem); }
  .article-shell { padding-top: 42px; }
  .article-header, .article-hero, .article-layout, .article-footer { width: min(calc(100% - 28px), 100%); }
  .article-title { font-size: clamp(2.8rem, 14vw, 5.3rem); }
  .article-hero { margin-top: 30px; margin-bottom: 38px; }
  .article-hero img { height: auto; }
  .post-content { font-size: 1.05rem; line-height: 1.8; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-grid > :first-child { grid-column: auto; }
}

/* Visible keyboard focus (accessibility). Only shows for keyboard/AT users via
   :focus-visible, so mouse clicks stay clean. Placed late so it wins over the
   `outline: none` on the search and subscribe inputs. */
a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
summary:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}
.search-row input:focus-visible,
.subscribe-input:focus-visible { outline-offset: 1px; }

@media (prefers-reduced-motion: reduce) {
  *, *:before, *:after { scroll-behavior: auto !important; transition: none !important; animation: none !important; }
}

body.script:
//
(function () {
  var root = document.documentElement;
  var themeToggle = document.getElementById('themeToggle');
  // Initial dark class is set by the inline <head> script to avoid a flash:
  // the reader's saved choice, otherwise their system setting.
  function setDark(isDark) {
    root.classList.toggle('dark', isDark);
    var meta = document.querySelector('meta[name=theme-color]');
