    if (!searchOverlay || searchIsOpen()) return;
    searchPreviousFocus = document.activeElement;
    searchOverlay.classList.add('open');
    searchOverlay.setAttribute('aria-hidden', 'false');
    if (siteShell) siteShell.setAttribute('inert', '');
