  // A card snippet is the start of the paper's text, which is usually the lead
  // photo's credit and the audio player's fallback text. Drop those so each card
  // opens with the essay itself, and mark papers that have an audio edition.
  (function cleanCardSnippets() {
    var hasAudio = /az-studio\.web\.app\/embed\/audio|\bListen to this paper\b|\bElevenLabs_/i;
    var audioMarker = /\bListen to this paper\b[\s\S]*?(?:\bOpen audio in a new tab\b\.?|$)/i;
    var voiceFile = /[^.!?]{0,80}?\bElevenLabs_\S*\s*/;
    var credit = new RegExp([
      '\\b(?:unsplash|wikimedia(?:\\s+commons)?|pexels|pixabay|flickr|getty(?:\\s+images)?|public\\s+domain|cc0|cc\\s+by(?:[-\\s](?:sa|nc|nd))*(?:\\s+\\d(?:\\.\\d)?)?)\\b(?:\\s*\\([^)]{0,40}\\))?\\s*[.;,]*',
      '\\b(?:photo(?:graph)?|image|illustration)\\s+by\\s[^.!?]{1,80}?(?:[.!?](?=\\s|$)|$)',
      '\\b(?:photo(?:graph)?|image|illustration|credit|source)s?\\s*:\\s*[^.!?]{1,80}?(?:[.!?](?=\\s|$)|$)'
    ].join('|'), 'gi');
    var pictured = /^The (?:person|people|individuals?|man|woman) (?:pictured|shown|depicted)[^.!?]*[.!?]\s*/i;

    Array.prototype.forEach.call(document.querySelectorAll('.post-card .post-snippet'), function (snippet) {
      try {
        var card = snippet.closest('.post-card');
        var text = (snippet.textContent || '').replace(/\s+/g, ' ').trim();
        var cut = /(?:\.{3}|\u2026)$/.test(text);
        var meta = card.querySelector('.post-meta');
        if (meta && hasAudio.test(text)) {
          var flag = document.createElement('span');
          flag.className = 'dot';
          flag.innerHTML = '<span class="post-audio-flag">Audio edition</span>';
          var read = meta.querySelector('.read-link');
          meta.insertBefore(flag, read ? read.closest('.dot') : null);
        }

        text = text.replace(/(?:\.{3}|\u2026)$/, '').replace(audioMarker, ' ').replace(voiceFile, ' ');
        // Defensive: drop any CSS text a snippet picked up from an embed's style block.
        while (/\{[^{}]*\}/.test(text)) text = text.replace(/(?:@media[^{]*|[^\s{}]*)\{[^{}]*\}/g, ' ');
        text = text.replace(/[^\s{}]*\{[\s\S]*$/, '');
        // Captions exist only on cards with an image: cut through the last credit
        // found near the start (descriptive captions name their source last).
        if (card.querySelector('.post-card-media img')) {
          var end = 0, match;
          credit.lastIndex = 0;
          while ((match = credit.exec(text)) && match.index < 260) {
            end = match.index + match[0].length;
            if (!match[0].length) credit.lastIndex++;
          }
          if (end) text = text.slice(end);
        }
        text = text.replace(/^[\s.,;:\u00b7\u2022|\u2013\u2014-]+/, '').replace(pictured, '');
        text = text.replace(/\s+([.,;:!?])/g, '$1').replace(/\s{2,}/g, ' ').trim();
        if (cut) text = text.replace(/\s+\S*$/, '');

        var limit = card.matches(':first-child') ? 260 : 170;
        var ellipsis = function (t) {
          t = t.replace(/[,;:]$/, '');
          return /[.!?\u2026]["'\u201d\u2019)]?$/.test(t) ? t : t + '\u2026';
        };
        if (text.length > limit) text = ellipsis(text.slice(0, limit).replace(/\s+\S*$/, ''));
        else if (cut && text) text = ellipsis(text);
        if (text.length < 40) snippet.remove();
        else snippet.textContent = text;
      } catch (e) {}
    });
  })();

  // Cards use one broad section plus one useful topic. This keeps the existing
  // Blogger labels searchable without turning the homepage into a tag cloud.
  (function simplifyDisplayedLabels() {
    var sectionOrder = ['Travel', 'Culture', 'Business', 'Technology', 'Life', 'Ideas'];
    var sectionSet = {};
    sectionOrder.forEach(function (name) { sectionSet[name] = true; });
    function normalized(name) { return name === 'Artificial Intelligence' ? 'AI' : name; }

    Array.prototype.forEach.call(document.querySelectorAll('.post-labels, .article-kicker'), function (wrap) {
      var links = Array.prototype.slice.call(wrap.querySelectorAll('a'));
      var limit = wrap.classList.contains('article-kicker') ? 3 : 2;
      var seen = {}, unique = [];
      links.forEach(function (link) {
        var name = normalized((link.textContent || '').trim());
        if (!name || name === 'The Pwavwe Papers' || seen[name]) return;
        seen[name] = true;
        link.textContent = name;
        unique.push(link);
      });

      var primary = null;
      sectionOrder.some(function (section) {
        primary = unique.filter(function (link) { return link.textContent === section; })[0] || null;
        return !!primary;
      });
      var topic = unique.filter(function (link) { return link !== primary && !sectionSet[link.textContent]; })[0] || null;
      var chosen = [];
      if (primary) chosen.push(primary);
      if (topic) chosen.push(topic);
      unique.forEach(function (link) { if (chosen.length < limit && chosen.indexOf(link) === -1) chosen.push(link); });

      wrap.textContent = '';
      chosen.forEach(function (link, index) {
        if (index && wrap.classList.contains('article-kicker')) wrap.appendChild(document.createTextNode(' \u00b7 '));
        wrap.appendChild(link);
      });
      if (!chosen.length) wrap.remove();
    });
  })();

  // One lazy Firebase loader serves the article and footer forms. The
  // local receipt prevents repeated writes from the same browser; Firestore
  // rules remain the authoritative server-side shape and permission check.
  var newsletterConfig = {apiKey:"AIzaSyB6lxgjNY4CRNHAe3pAgR5SYv1ohL8brOI",authDomain:"francis-pwavwe.firebaseapp.com",projectId:"francis-pwavwe",storageBucket:"francis-pwavwe.firebasestorage.app",messagingSenderId:"658069378543",appId:"1:658069378543:web:87b1dcb0dd27d3255bd21a"};
  var newsletterLoading = null;
  var newsletterSubscribedKey = 'pwavwe-newsletter-subscribed';
  var newsletterAttemptKey = 'pwavwe-newsletter-last-attempt';

  function newsletterStorageGet(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; }
  }
  function newsletterStorageSet(key, value) {
    try { localStorage.setItem(key, value); } catch (e) {}
  }
  function loadNewsletterScript(src) {
    return new Promise(function (resolve, reject) {
      var existing = document.querySelector('script[data-fb-src="' + src + '"]');
      if (existing) {
        if (existing.getAttribute('data-loaded')) resolve();
        else { existing.addEventListener('load', resolve, {once:true}); existing.addEventListener('error', reject, {once:true}); }
        return;
      }
      var script = document.createElement('script');
      script.src = src;
      script.async = true;
      script.setAttribute('data-fb-src', src);
      script.addEventListener('load', function () { script.setAttribute('data-loaded', '1'); resolve(); }, {once:true});
      script.addEventListener('error', reject, {once:true});
      document.head.appendChild(script);
    });
  }
  function newsletterDb() {
    if (!newsletterLoading) {
      newsletterLoading = loadNewsletterScript('https://www.gstatic.com/firebasejs/10.12.0/firebase-app-compat.js')
        .then(function () { return loadNewsletterScript('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore-compat.js'); });
    }
    return newsletterLoading.then(function () {
      if (!firebase.apps.length) firebase.initializeApp(newsletterConfig);
      return firebase.firestore();
    });
  }
  function bindNewsletter(formId, emailId, honeypotId, messageId, source, onSuccess) {
    var form = document.getElementById(formId);
    var email = document.getElementById(emailId);
    var message = document.getElementById(messageId);
    if (!form || !email) return;

    email.addEventListener('focus', function () { newsletterDb().catch(function () {}); }, {once:true});
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      var honeypot = document.getElementById(honeypotId);
      if (honeypot && honeypot.value) return;
      if (!email.value.trim() || !form.checkValidity()) { form.reportValidity(); return; }
      if (newsletterStorageGet(newsletterSubscribedKey) === 'true') {
        if (message) message.textContent = 'You are already on the list — thank you.';
        return;
      }
      var lastAttempt = parseInt(newsletterStorageGet(newsletterAttemptKey), 10) || 0;
      if (Date.now() - lastAttempt < 10000) {
        if (message) message.textContent = 'Please wait a moment before trying again.';
        return;
      }
      newsletterStorageSet(newsletterAttemptKey, String(Date.now()));
      var button = form.querySelector('button[type="submit"]');
      if (button) button.disabled = true;
      if (message) message.textContent = 'One moment\u2026';
      newsletterDb().then(function (db) {
        return db.collection('subscribers').add({ email: email.value.trim().toLowerCase(), source: source, status: 'subscribed', timestamp: firebase.firestore.FieldValue.serverTimestamp() });
      }).then(function () {
        newsletterStorageSet(newsletterSubscribedKey, 'true');
        form.reset();
        // The form gives way to the confirmation; focus follows so keyboard
        // users are not left on a hidden button.
        var focusWasInForm = form.contains(document.activeElement) || document.activeElement === document.body;
        form.hidden = true;
        if (message) {
          message.textContent = 'You are in \u2014 thanks for subscribing.';
          message.classList.add('subscribe-note--ok');
          if (focusWasInForm) { message.setAttribute('tabindex', '-1'); message.focus(); }
        }
        document.dispatchEvent(new CustomEvent('pwavwe:subscribed'));
        if (onSuccess) onSuccess();
      }).catch(function (error) {
        if (message) message.textContent = 'Hmm, that did not save. Please try again.';
        console.error(error);
      }).then(function () { if (button) button.disabled = false; });
    });
  }

  bindNewsletter('fp-sub', 'fp-email', 'fp-website', 'fp-msg', 'blog');
