  // The Blogger comment iframe, reCAPTCHA and supporting scripts stay inert
  // inside a template until the reader explicitly opens the discussion.
  var commentsGate = document.getElementById('commentsGate');
  var commentsTemplate = document.getElementById('commentsTemplate');
  var commentsMount = document.getElementById('commentsMount');
  if (commentsGate && commentsTemplate && commentsMount) {
    commentsGate.addEventListener('toggle', function () {
      if (!commentsGate.open || commentsGate.getAttribute('data-loaded')) return;
      commentsGate.setAttribute('data-loaded', 'true');
      var fragment = commentsTemplate.content.cloneNode(true);
      Array.prototype.forEach.call(fragment.querySelectorAll('iframe'), function (frame) {
        frame.setAttribute('loading', 'lazy');
        if (!frame.getAttribute('title')) frame.setAttribute('title', 'Blogger comments');
      });
      // Scripts cloned from a template are inert. Run them in document order,
      // waiting for each external dependency before the following inline script.
      // Blogger's iframe initializer otherwise runs before its library is ready,
      // leaving a blank comment box that cannot receive input.
      var scripts = Array.prototype.map.call(fragment.querySelectorAll('script'), function (oldScript) {
        var descriptor = {attributes: [], text: oldScript.textContent || ''};
        Array.prototype.forEach.call(oldScript.attributes, function (attr) {
          descriptor.attributes.push({name: attr.name, value: attr.value});
        });
        oldScript.parentNode.removeChild(oldScript);
        return descriptor;
      });
      commentsMount.appendChild(fragment);
      commentsTemplate.remove();

      function runCommentScript(index) {
        if (index >= scripts.length) return;
        var descriptor = scripts[index];
        var script = document.createElement('script');
        Array.prototype.forEach.call(descriptor.attributes, function (attr) {
          script.setAttribute(attr.name, attr.value);
        });
        if (script.src) {
          script.onload = function () { runCommentScript(index + 1); };
          script.onerror = function () { runCommentScript(index + 1); };
        } else {
          script.text = descriptor.text;
        }
        commentsMount.appendChild(script);
        if (!script.src) runCommentScript(index + 1);
      }

      runCommentScript(0);
    });
  }

  var content = document.getElementById('postContent');
  if (content) {
    // The first AZ Studio or SoundCloud embed is the paper's read version. For
    // SoundCloud, keep its original track URL (including any secret token) and
    // the chosen player height.
    var paperAudio = null;
    (function preparePaperAudio() {
      var audio = document.getElementById('paperAudio');
      var mount = document.getElementById('paperAudioPlayer');
      var link = document.getElementById('paperAudioLink');
      if (!audio || !mount || !link) return;
      var frames = content.querySelectorAll('iframe[src]');
      for (var i = 0; i < frames.length; i++) {
        var frame = frames[i];
        var playerUrl;
        try { playerUrl = new URL(frame.getAttribute('src'), window.location.href); }
        catch (e) { continue; }

        // AZ Studio embeds are a self-contained block. Move the whole block so
        // its styles travel with it; the audio script below themes and sizes it.
        var embed = frame.closest('.pwavwe-audio-embed');
        if (embed && playerUrl.origin === 'https://az-studio.web.app' && /^\/embed\/audio\/[\w-]+\/?$/.test(playerUrl.pathname)) {
          var openUrl = new URL(playerUrl.href);
          openUrl.searchParams.set('theme', 'auto');
          link.href = openUrl.href;
          playerUrl.searchParams.delete('theme');
          paperAudio = { embedUrl: playerUrl.href, url: playerUrl.href };
          mount.appendChild(embed);
