          break;
        }

        if (playerUrl.hostname !== 'w.soundcloud.com' || !/^\/player\/?$/.test(playerUrl.pathname)) continue;
        if (!/^https?:$/.test(playerUrl.protocol) || !playerUrl.searchParams.get('url')) continue;
        playerUrl.protocol = 'https:';
        playerUrl.searchParams.set('auto_play', 'false');
        frame.setAttribute('src', playerUrl.href);
        frame.setAttribute('title', 'Listen to ' + (content.getAttribute('data-post-title') || 'this paper') + ' on SoundCloud');
        frame.setAttribute('loading', 'lazy');
        frame.setAttribute('width', '100%');
        link.href = playerUrl.href;
        function soundCloudLink(value) {
          try {
            var url = new URL(value);
            if (url.protocol === 'https:' && /^(www\.)?soundcloud\.com$/.test(url.hostname)) return url.href;
          } catch (e) {}
          return '';
