        // Keep it with the player, without moving neighbouring article prose.
        var credit = frame.nextElementSibling;
        if (credit && credit.tagName === 'DIV' && /font-size\s*:\s*10px/i.test(credit.getAttribute('style') || '')) {
          var creditLinks = Array.prototype.slice.call(credit.querySelectorAll('a[href]'));
          if (creditLinks.length && creditLinks.every(function (a) { return !!soundCloudLink(a.href); })) {
            credit.removeAttribute('style');
            credit.classList.add('paper-audio-credit');
