      var isLeadImage = lead.tagName === 'IMG' || lead.tagName === 'FIGURE' ||
        lead.classList.contains('separator') || lead.matches('table.tr-caption-container') ||
        (lead.tagName === 'P' && !(lead.textContent || '').trim());
