    // its last full sentence rather than mid-word.
    var dek = document.querySelector('.article-dek');
    if (dek) {
      var dekText = (dek.textContent || '').replace(/\s+/g, ' ').trim();
      if (dekText && !/[.!?…"'”’)]$/.test(dekText)) {
        var stop = Math.max(dekText.lastIndexOf('. '), dekText.lastIndexOf('! '), dekText.lastIndexOf('? '));
        dekText = stop > 40 ? dekText.slice(0, stop + 1) : dekText.replace(/\s+\S*$/, '') + '…';
      }
      if (dekText) dek.textContent = dekText;
