    if (paperAudio && byline) {
      var listen = document.createElement('a');
      listen.className = 'byline-audio';
      listen.href = '#paperAudio';
      listen.innerHTML = '<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24"><path d="M4 15v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="14" width="5" height="7" rx="2"/><rect x="16" y="14" width="5" height="7" rx="2"/></svg><span>Listen instead</span>';
      byline.appendChild(listen);
