    // A related case study on pwavwe.com, added at the end of a paper as
    // <p class="case-study-link"><a href="https://pwavwe.com/work/SLUG">…</a></p>.
    // Known projects get their name and one-line summary; any other /work/ page
    // keeps the link's own text as its title.
    (function caseStudyLinks() {
      var studies = {
        'comitia': ['Comitia', 'A managed online elections platform, from voter setup to verified public results.'],
        'vitaforge-ai': ['VitaForge AI', 'A student-first AI career platform for stronger, more deliberate job applications.'],
        'smg-transport-agency': ['SMG Transport Agency', 'An intercity travel booking workflow covering route discovery, seats, payment and QR tickets.'],
