      };
      Array.prototype.forEach.call(content.querySelectorAll('.case-study-link a[href*="pwavwe.com/work/"]'), function (link) {
        var slug = link.pathname.replace(/\/+$/, '').replace(/\.html$/, '').split('/').pop();
        var study = studies[slug];
        var parts = [
          ['case-study-kicker', 'Pwavwe Studio case study'],
          ['case-study-title', study ? study[0] : (link.textContent || '').trim()],
          ['case-study-summary', study ? study[1] : ''],
          ['case-study-cta', study ? 'Read the case study →' : '']
        ];
        link.textContent = '';
        parts.forEach(function (part) {
          if (!part[1]) return;
          var span = document.createElement('span');
          span.className = part[0];
          span.textContent = part[1];
          link.appendChild(span);
        });
      });
    })();

    // The opening paragraph is set slightly larger to ease the reader in.
    (function markLede() {
      var paragraphs = content.querySelectorAll('p');
      for (var i = 0; i < paragraphs.length; i++) {
        var p = paragraphs[i];
        if (p.closest('figure, blockquote, li, table, .pwavwe-audio-embed, .case-study-link')) continue;
        if ((p.textContent || '').trim().length < 60 || !p.getClientRects().length) continue;
        p.classList.add('lede');
        break;
      }
    })();

    Array.prototype.forEach.call(content.querySelectorAll('img'), function (image) {
      image.setAttribute('loading', 'lazy');
      image.setAttribute('decoding', 'async');
    });
    var words = (content.innerText || content.textContent || '').trim().split(/\s+/).filter(Boolean).length;
    var minutes = Math.max(1, Math.ceil(words / 220));
    var readingTime = document.getElementById('readingTime');
    if (readingTime) readingTime.textContent = minutes + ' min read';

    // Structured data (JSON-LD) for this paper. Built here rather than in the
    // template so titles/descriptions are escaped safely via JSON.stringify.
    (function () {
      function metaOf(sel) { var m = document.querySelector(sel); return m ? (m.getAttribute('content') || '').trim() : ''; }
      var canonEl = document.querySelector('link[rel="canonical"]');
      var canonical = (canonEl && canonEl.href) || window.location.href;
      var title = (content.getAttribute('data-post-title') || document.title || '').trim();
      var desc = metaOf('meta[name="description"]') || metaOf('meta[property="og:description"]');
      var heroImg = document.querySelector('.article-hero img');
      var image = metaOf('meta[property="og:image"]') || (heroImg && heroImg.src) || '';
      var published = metaOf('meta[itemprop="datePublished"]');
      var modified = metaOf('meta[itemprop="dateModified"]') || published;
      // Same @id as the Person on pwavwe.com, so search engines join the two.
      var author = { '@type': 'Person', '@id': 'https://pwavwe.com/#francis', name: 'Francis Pwavwe', url: 'https://pwavwe.com/' };

      var post = {
        '@context': 'https://schema.org',
        '@type': 'BlogPosting',
        mainEntityOfPage: { '@type': 'WebPage', '@id': canonical },
        headline: title,
        url: canonical,
        author: author,
        publisher: author,
        inLanguage: 'en'
      };
      if (desc) post.description = desc;
      if (image) post.image = image;
      if (published) post.datePublished = published;
      if (modified) post.dateModified = modified;
      if (paperAudio) {
        post.audio = {
          '@type': 'AudioObject',
          name: title + ' (audio edition)',
          embedUrl: paperAudio.embedUrl,
          url: paperAudio.url,
          inLanguage: 'en'
        };
      }

      var crumbs = [{ '@type': 'ListItem', position: 1, name: 'Home', item: 'https://blogs.pwavwe.com/' }];
      var firstLabel = document.querySelector('.article-kicker a');
      if (firstLabel) {
        crumbs.push({ '@type': 'ListItem', position: 2, name: (firstLabel.textContent || '').trim(), item: firstLabel.href });
      }
      crumbs.push({ '@type': 'ListItem', position: crumbs.length + 1, name: title, item: canonical });
      var breadcrumb = { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: crumbs };

      [post, breadcrumb].forEach(function (obj) {
        var s = document.createElement('script');
        s.type = 'application/ld+json';
        s.text = JSON.stringify(obj);
        document.head.appendChild(s);
      });
    })();

    // Contents: one heading list feeds the desktop rail and the phone/tablet
    // panel, and the entry for the section being read is highlighted.
    var headings = Array.prototype.filter.call(content.querySelectorAll('h2, h3'), function (h) {
      return (h.textContent || '').trim() && h.getClientRects().length;
    });
    var tocNavs = ['toc', 'tocMobileNav'].map(function (id) { return document.getElementById(id); }).filter(Boolean);
    var tocEntries = [];
    if (headings.length > 1) {
      headings.forEach(function (h, i) {
        if (!h.id) h.id = 'section-' + (i + 1);
        tocEntries.push({ heading: h, links: tocNavs.map(function (nav) {
          var a = document.createElement('a');
          a.href = '#' + h.id;
          a.textContent = h.textContent.trim();
          if (h.tagName === 'H3') a.className = 'toc-sub';
          nav.appendChild(a);
          return a;
        }) });
      });
      var tocMobile = document.getElementById('tocMobile');
      if (tocMobile) {
        var tocCount = tocMobile.querySelector('.toc-count');
        if (tocCount) tocCount.textContent = headings.length + ' sections';
        tocMobile.hidden = false;
        tocMobile.addEventListener('click', function (e) {
          if (e.target.closest && e.target.closest('a')) tocMobile.open = false;
        });
      }
    } else {
      var railToc = document.getElementById('toc');
      if (railToc) {
        railToc.classList.add('toc--empty');
        railToc.innerHTML = '<span class="toc-empty">A clean, uninterrupted read.</span>';
      }
    }

    var progress = document.getElementById('readingProgress');
    var activeEntry = null;
    function updateReading() {
      var viewport = window.innerHeight;
      if (progress) {
        var articleTop = content.getBoundingClientRect().top + window.scrollY;
        var total = Math.max(1, content.offsetHeight - viewport * 0.45);
        var current = window.scrollY - articleTop + viewport * 0.2;
        progress.style.width = Math.min(100, Math.max(0, (current / total) * 100)) + '%';
      }
      if (!tocEntries.length) return;
      var next = null;
      for (var i = 0; i < tocEntries.length; i++) {
        if (tocEntries[i].heading.getBoundingClientRect().top - 140 > 0) break;
        next = tocEntries[i];
      }
      if (next === activeEntry) return;
      if (activeEntry) activeEntry.links.forEach(function (a) { a.classList.remove('is-active'); a.removeAttribute('aria-current'); });
      activeEntry = next;
      if (activeEntry) activeEntry.links.forEach(function (a) { a.classList.add('is-active'); a.setAttribute('aria-current', 'location'); });
    }
    var readingFrame = 0;
    function scheduleReading() {
      if (readingFrame) return;
      readingFrame = window.requestAnimationFrame(function () { readingFrame = 0; updateReading(); });
    }
    updateReading();
    window.addEventListener('scroll', scheduleReading, {passive:true});
    window.addEventListener('resize', scheduleReading);

    // Share controls exist twice (side rail and the row under the author box),
    // so they are wired by data-share. Share the canonical URL, not ?m=1.
    var canonicalLink = document.querySelector('link[rel="canonical"]');
    var shareUrl = (canonicalLink && canonicalLink.href) || window.location.href.split('#')[0];
    var shareTitle = content.getAttribute('data-post-title') || document.title;
    var shareStatus = document.getElementById('shareStatus');
    var shareLinks = {
      x: 'https://twitter.com/intent/tweet?url=' + encodeURIComponent(shareUrl) + '&text=' + encodeURIComponent(shareTitle),
      linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + encodeURIComponent(shareUrl),
      whatsapp: 'https://wa.me/?text=' + encodeURIComponent(shareTitle + ' ' + shareUrl),
      facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(shareUrl)
    };
    function copyShareLink(button) {
      var label = button.getAttribute('data-label') || button.textContent;
      button.setAttribute('data-label', label);
      function done(ok) {
        button.textContent = ok ? 'Copied ✓' : 'Copy failed';
        if (shareStatus) shareStatus.textContent = ok ? 'Link copied.' : 'The link could not be copied.';
        setTimeout(function () { button.textContent = label; }, 1600);
      }
      function fallback() {
        var field = document.createElement('textarea');
        field.value = shareUrl;
        field.setAttribute('readonly', '');
        field.style.cssText = 'position:fixed;top:0;left:0;opacity:0';
        document.body.appendChild(field);
        field.select();
        var ok = false;
        try { ok = document.execCommand('copy'); } catch (e) {}
        field.remove();
        done(ok);
      }
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(shareUrl).then(function () { done(true); }, fallback);
      } else {
        fallback();
      }
    }
    Array.prototype.forEach.call(document.querySelectorAll('[data-share]'), function (control) {
      var kind = control.getAttribute('data-share');
      if (kind === 'copy') control.addEventListener('click', function () { copyShareLink(control); });
      else if (shareLinks[kind]) control.href = shareLinks[kind];
    });

    // Continue reading: up to three papers from this one's topic label (the
    // closer match), topped up from its broader section. The kicker already
    // shows [section, topic]; read the label names from its links, because the
    // displayed text may be shortened (Artificial Intelligence shows as AI).
    var relatedWrap = document.getElementById('related');
    var relatedGrid = document.getElementById('relatedGrid');
    if (relatedWrap && relatedGrid) {
      var relatedLabels = [];
      Array.prototype.forEach.call(document.querySelectorAll('.article-kicker a'), function (a) {
        var m = /\/search\/label\/([^?#]+)/.exec(a.getAttribute('href') || '');
        if (m) relatedLabels.push(decodeURIComponent(m[1]));
      });
      if (relatedLabels.length > 1) relatedLabels = [relatedLabels[1], relatedLabels[0]];
      if (!relatedLabels.length) {
        var labelEl = document.getElementById('relatedLabel');
        if (labelEl && labelEl.textContent.trim()) relatedLabels.push(labelEl.textContent.trim());
      }
      var relatedPicks = [], relatedSeen = {};
      relatedSeen[(relatedWrap.getAttribute('data-current') || window.location.href).split(/[?#]/)[0]] = true;
      var fetchRelated = function (index) {
        if (relatedPicks.length >= 3 || index >= relatedLabels.length) return Promise.resolve();
        return fetch('/feeds/posts/summary/-/' + encodeURIComponent(relatedLabels[index]) + '?alt=json&max-results=6')
          .then(function (r) { return r.ok ? r.json() : null; })
          .then(function (json) {
            ((json && json.feed && json.feed.entry) || []).forEach(function (e) {
              if (relatedPicks.length >= 3) return;
              var href = '';
              (e.link || []).forEach(function (l) { if (l.rel === 'alternate') href = l.href; });
              var key = href.split(/[?#]/)[0];
              if (!href || relatedSeen[key]) return;
              relatedSeen[key] = true;
              var thumb = (e.media$thumbnail && e.media$thumbnail.url) || '';
              relatedPicks.push({
                href: href,
                title: (e.title && e.title.$t) || 'Untitled paper',
                thumb: thumb.replace(/\/s72-c\//, '/w600-h375-c/').replace(/=s72-c$/, '=w600-h375-c')
              });
            });
            return fetchRelated(index + 1);
          });
      };
      fetchRelated(0).then(function () {
        if (!relatedPicks.length) return;
        relatedPicks.forEach(function (p) {
          var card = document.createElement('a');
          card.className = 'related-card';
          card.href = p.href;
          var thumb = document.createElement('span');
          thumb.className = p.thumb ? 'related-thumb' : 'related-thumb related-thumb--empty';
          if (p.thumb) thumb.style.backgroundImage = 'url("' + p.thumb.replace(/"/g, '%22') + '")';
          var title = document.createElement('span');
          title.className = 'related-title';
          title.textContent = p.title;
          card.appendChild(thumb);
          card.appendChild(title);
          relatedGrid.appendChild(card);
        });
        relatedWrap.style.display = '';
      }).catch(function () {});
    }

  }
})();
//

