/* The Pwavwe Papers audio player: keep embedded players on the blog's theme, and size them to their content. */
(function () {
  var ORIGIN = "https://az-studio.web.app";
  function frames() { return document.querySelectorAll('.pwavwe-audio-embed iframe'); }
  function currentTheme() { return document.documentElement.classList.contains('dark') ? 'dark' : 'light'; }
  function send() {
    var theme = currentTheme();
    Array.prototype.forEach.call(frames(), function (f) {
      if (f.contentWindow) f.contentWindow.postMessage({ type: 'pwavwe-player-theme', theme: theme }, ORIGIN);
    });
  }
  window.addEventListener('message', function (e) {
    if (e.origin !== ORIGIN || !e.data || e.data.type !== 'pwavwe-player-size') return;
    var h = Number(e.data.height);
    if (h > 0 && h <= 600) {
      Array.prototype.forEach.call(frames(), function (f) {
        if (f.contentWindow === e.source) f.style.height = Math.round(h) + 'px';
      });
    }
    send();
  });
  // Posts embed the player as ?theme=light. Match the reader's theme in the URL
  // so a lazy-loaded player starts in the right colours instead of flashing light.
  // Embeds can finish loading after window load, so theme each one as it arrives.
  Array.prototype.forEach.call(frames(), function (f) {
    try {
      var url = new URL(f.getAttribute('src'), window.location.href);
      if (url.origin === ORIGIN && url.searchParams.get('theme') !== currentTheme()) {
        url.searchParams.set('theme', currentTheme());
        f.setAttribute('src', url.href);
      }
    } catch (e) {}
    f.addEventListener('load', send);
  });
  new MutationObserver(send).observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
  window.addEventListener('load', send);
})();
//
